INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','easy','mcq','Which of the following best describes the peripheral blood smear findings in established iron deficiency anaemia?','["A) Microcytic, hypochromic red cells with pencil cells and enlarged zone of central pallor", "B) Macrocytic, normochromic red cells with hypersegmented neutrophils", "C) Normocytic, normochromic red cells with target cells", "D) Spherocytes and polychromasia with increased reticulocyte count"]','A','In iron deficiency anaemia the red cells are small (microcytic) and pale (hypochromic) due to insufficient haemoglobin. The zone of central pallor is enlarged beyond the normal one-third of cell diameter, and elongated pencil cells are characteristic.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','easy','mcq','What is the most common cause of iron deficiency anaemia in the Western world?','["A) Dietary lack of iron", "B) Chronic blood loss", "C) Impaired iron absorption due to coeliac disease", "D) Increased iron requirements during pregnancy"]','B','Chronic blood loss is the most common cause of iron deficiency anaemia in the Western world. In adult men and post-menopausal women, iron deficiency must be attributed to gastrointestinal blood loss until proven otherwise, as it may signal an occult malignancy.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','medium','mcq','A 35-year-old woman presents with fatigue and pallor. Lab results: serum iron low, TIBC elevated, ferritin 8 µg/L, transferrin saturation 10%. Which is the most likely diagnosis?','["A) Anaemia of chronic disease", "B) Beta-thalassaemia trait", "C) Iron deficiency anaemia", "D) Sideroblastic anaemia"]','C','The combination of low serum iron, elevated TIBC (reflecting elevated transferrin), reduced transferrin saturation below 15%, and a very low serum ferritin (below 12 µg/L) is diagnostic of iron deficiency anaemia. In anaemia of chronic disease, ferritin is typically normal or elevated.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','medium','mcq','Which hormone plays a central role in regulating iron absorption in response to body iron stores?','["A) Erythropoietin", "B) Transferrin", "C) Ferritin", "D) Hepcidin"]','D','Hepcidin is a small peptide synthesised by the liver that inhibits iron transfer from enterocytes and macrophages by binding to ferroportin and causing its degradation. When body iron stores are replete, hepcidin levels rise. In iron deficiency, hepcidin falls, allowing greater iron uptake.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','medium','mcq','A bone marrow aspirate from a patient with suspected iron deficiency is stained with Prussian blue. What is the expected finding?','["A) Absence of stainable iron in marrow macrophages", "B) Increased iron deposits in macrophages", "C) Ringed sideroblasts with iron-laden mitochondria", "D) Normal iron distribution with haemosiderin in erythroid precursors"]','A','A diagnostically significant finding in iron deficiency anaemia is the disappearance of stainable iron from bone marrow macrophages on Prussian blue staining. This represents depletion of storage iron, in contrast to anaemia of chronic disease where macrophage iron is abundant but unavailable.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','hard','mcq','Which clinical features constitute the Plummer-Vinson syndrome triad seen in severe longstanding iron deficiency?','["A) Hepatosplenomegaly, atrophic glossitis, and oesophageal web", "B) Microcytic hypochromic anaemia, atrophic glossitis, and oesophageal web", "C) Microcytic anaemia, koilonychia, and peripheral neuropathy", "D) Pica, peripheral neuropathy, and oesophageal varices"]','B','Plummer-Vinson syndrome consists of the triad of microcytic hypochromic anaemia, atrophic glossitis, and oesophageal webs. It results from iron deficiency causing depletion of iron-containing enzymes throughout the body, including those in mucosal cells.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','easy','mcq','What percentage of ingested heme iron is absorbable compared to non-heme iron?','["A) About 1-2% heme vs 20% non-heme", "B) About 50% heme vs 25% non-heme", "C) About 20% heme vs 1-2% non-heme", "D) About 10% heme vs 10% non-heme"]','C','Approximately 20% of heme iron from animal products is absorbable, whereas only 1-2% of non-heme (inorganic) iron from plant sources is absorbed. This explains the higher prevalence of iron deficiency in populations whose diets rely predominantly on plant foods.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','medium','mcq','In the progression of iron deficiency, at which stage does anaemia first appear?','["A) When serum iron begins to fall below normal", "B) At the same time as serum iron and transferrin saturation begin to decrease", "C) When serum ferritin falls below 50 µg/L", "D) Only after iron stores are completely depleted and transferrin saturation falls"]','D','Iron deficiency progresses in stages. Initially iron stores buffer the deficit; serum iron and transferrin saturation fall first without producing anaemia. Anaemia only develops once iron stores are completely depleted, accompanied by low serum iron, ferritin, and transferrin saturation below 15%.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','hard','mcq','A rare form of microcytic anaemia fails to respond to oral iron therapy due to a mutation in TMPRSS6. What is the mechanism?','["A) TMPRSS6 mutation disables a hepatic serine protease that normally suppresses hepcidin, leading to persistently high hepcidin and impaired iron absorption", "B) TMPRSS6 mutation prevents intestinal absorption of ferrous iron via DMT1", "C) TMPRSS6 mutation results in increased ferroportin expression, trapping iron in enterocytes", "D) TMPRSS6 mutation reduces transferrin synthesis, limiting iron transport to erythroid precursors"]','A','TMPRSS6 is a hepatic transmembrane serine protease that normally suppresses hepcidin production when iron stores are low. Mutations disabling TMPRSS6 result in abnormally elevated hepcidin levels, which inhibit ferroportin and prevent iron absorption from the gut, causing microcytic anaemia refractory to oral iron.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','medium','mcq','A 60-year-old man has iron deficiency anaemia with no obvious dietary cause. What is the most important next investigation?','["A) Serum hepcidin level", "B) Evaluation for gastrointestinal blood loss including colonoscopy", "C) Bone marrow biopsy to assess iron stores", "D) Haemoglobin electrophoresis to exclude thalassaemia trait"]','B','Iron deficiency in adult men and post-menopausal women must be attributed to gastrointestinal blood loss until proven otherwise. Prematurely ascribing it to dietary inadequacy risks missing an occult gastrointestinal cancer or other bleeding lesion — endoscopic evaluation is mandatory.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','easy','mcq','Which peripheral blood finding is most characteristic of megaloblastic anaemia?','["A) Microcytic hypochromic red cells with target cells", "B) Spherocytes and polychromasia with elevated reticulocyte count", "C) Macro-ovalocytes and hypersegmented neutrophils with five or more nuclear lobes", "D) Pencil cells and poikilocytosis with low reticulocyte count"]','C','Megaloblastic anaemia is characterised by macro-ovalocytes (large oval red cells) and hypersegmented neutrophils (five or more nuclear lobes instead of the normal three to four). These findings result from impaired DNA synthesis affecting all rapidly dividing cells.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','easy','mcq','Pernicious anaemia results from autoimmune destruction of which gastric cell type?','["A) Chief cells, leading to reduced pepsin secretion", "B) G cells, leading to reduced gastrin production", "C) Mucous neck cells, leading to impaired gastric mucosal protection", "D) Parietal cells, leading to absent intrinsic factor and achlorhydria"]','D','Pernicious anaemia is caused by an autoimmune gastritis that destroys parietal cells of the fundic mucosa. This abolishes both intrinsic factor production (required for ileal vitamin B12 absorption) and hydrochloric acid secretion (achlorhydria), ultimately leading to vitamin B12 deficiency and megaloblastic anaemia.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','medium','mcq','Which biochemical abnormality distinguishes vitamin B12 deficiency from folate deficiency?','["A) Elevated serum methylmalonic acid in B12 deficiency but not in folate deficiency", "B) Elevated serum homocysteine in B12 deficiency only", "C) Elevated serum folate in B12 deficiency", "D) Reduced serum methylmalonic acid in B12 deficiency compared to folate deficiency"]','A','Both B12 and folate deficiency cause elevated serum homocysteine. However, only B12 deficiency leads to elevated methylmalonic acid, because B12 (as adenosylcobalamin) is required for the conversion of methylmalonyl-CoA to succinyl-CoA. Normal methylmalonate in megaloblastic anaemia points to folate rather than B12 deficiency.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','medium','mcq','A patient with pernicious anaemia develops progressive numbness, weakness, and spastic paraparesis of the lower limbs. Which pathological process underlies these neurological findings?','["A) Anterior horn cell degeneration due to nitric oxide toxicity", "B) Demyelination of dorsal and lateral spinal cord tracts — subacute combined degeneration", "C) Peripheral demyelination due to folate deficiency", "D) Cerebral cortical atrophy from homocysteine-induced atherosclerosis"]','B','Subacute combined degeneration of the spinal cord occurs in vitamin B12 deficiency and involves demyelination of the dorsal and lateral spinal cord tracts. Symptoms include sensory ataxia, spastic paraparesis, and paraesthesias. Folate therapy does not prevent and may worsen these neurological deficits.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','medium','mcq','Which of the following is the most common cause of folate deficiency?','["A) Terminal ileal resection interrupting ileal folate absorption", "B) Use of proton pump inhibitors reducing gastric acid", "C) Chronic alcoholism with poor dietary intake", "D) Autoimmune destruction of intestinal folate transporters"]','C','The most common cause of folate deficiency is inadequate dietary intake, most often seen in chronic alcoholics, the indigent, and the elderly. Alcohol also independently interferes with folate metabolism. Unlike vitamin B12 deficiency, folate stores are modest and deficiency can develop within weeks.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','hard','mcq','In vitamin B12 deficiency, megaloblastic anaemia develops due to folate trapping. Which specific metabolic reaction is most directly impaired?','["A) Conversion of methylmalonyl-CoA to succinyl-CoA by mutase", "B) Synthesis of purines from ribose-5-phosphate in the pentose phosphate pathway", "C) Methylation of homocysteine to methionine by methionine synthase", "D) Conversion of deoxyuridine monophosphate to deoxythymidine monophosphate by thymidylate synthase"]','D','When B12 is deficient, folate becomes trapped as N5-methyltetrahydrofolate. This depletes the active form (FH4), which is required as a cofactor in the conversion of dUMP to dTMP (thymidylate synthesis) by thymidylate synthase. The resulting impairment of DNA synthesis is the proximate cause of megaloblastosis.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','easy','mcq','Which type of antibody is most specific for the diagnosis of pernicious anaemia?','["A) Anti-intrinsic factor blocking antibodies (type I)", "B) Anti-gastric parietal cell antibodies (type III)", "C) Anti-transcobalamin II antibodies", "D) Anti-cubilin antibodies"]','A','Type I anti-intrinsic factor antibodies, found in about 75% of patients with pernicious anaemia, block the binding of vitamin B12 to intrinsic factor and are highly specific for pernicious anaemia. Anti-parietal cell antibodies (type III) are present in up to 90% but are also found in other gastritides, making them less specific.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','medium','mcq','A pregnant woman at 28 weeks gestation has megaloblastic anaemia. Serum B12 is normal but red cell folate is low. Which treatment is most appropriate?','["A) Parenteral vitamin B12 injections", "B) High-dose oral folic acid supplementation", "C) Iron infusion therapy", "D) Hydroxocobalamin with intrinsic factor"]','B','In pregnancy, folate requirements are significantly increased. A low red cell folate with normal B12 confirms folate deficiency. Folic acid supplementation is indicated; importantly, B12 deficiency must always be excluded first since folate therapy may mask B12 deficiency while allowing neurological deterioration to progress.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','hard','mcq','In the bone marrow of a patient with megaloblastic anaemia, the orthochromatic megaloblast is haemoglobinised yet its nucleus is not pyknotic. What does this demonstrate?','["A) Accelerated erythropoiesis with premature release of reticulocytes", "B) Ineffective erythropoiesis from premature destruction of fully mature erythrocytes", "C) Nuclear-to-cytoplasmic asynchrony: cytoplasmic maturation proceeds normally while nuclear maturation is delayed", "D) Reversal of normal haemoglobin synthesis due to excess folate polyglutamates"]','C','The hallmark of megaloblastic maturation is nuclear-to-cytoplasmic asynchrony. Cytoplasmic maturation (haemoglobin accumulation) proceeds at a normal pace, but nuclear maturation is delayed because impaired DNA synthesis prevents normal chromatin condensation, resulting in large cells with abundant haemoglobinised cytoplasm and an immature nucleus.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','medium','mcq','A patient has megaloblastic anaemia and is given folic acid. Within 5 days, reticulocytes increase markedly. However, the patient later develops worsening numbness in the legs. What is the most likely explanation?','["A) Folate therapy has corrected both haematological and neurological deficits", "B) The reticulocytosis has led to folate trapping, worsening B12 levels", "C) Folic acid excess has directly caused peripheral neuropathy", "D) The patient had underlying B12 deficiency; folate corrected the anaemia but neurological damage from B12 deficiency progressed"]','D','Folate therapy can correct the haematological manifestations of B12 deficiency (since folate is the proximate cause of megaloblastosis), but it cannot prevent and may even worsen the neurological complications of B12 deficiency. This is why B12 deficiency must be excluded before treating megaloblastic anaemia with folate alone.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','easy','mcq','Which of the following best describes the clinical triad of extravascular haemolysis?','["A) Anaemia, splenomegaly, and jaundice", "B) Anaemia, haemoglobinuria, and renal failure", "C) Anaemia, haemoglobinaemia, and haemosiderinuria", "D) Anaemia, thrombocytopenia, and lymphadenopathy"]','A','Extravascular haemolysis, where red cells are destroyed by macrophages in the spleen and liver, produces the clinical triad of anaemia, splenomegaly (from phagocyte hyperplasia), and jaundice (from unconjugated bilirubin). Haemoglobinaemia and haemoglobinuria are features of intravascular haemolysis.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','medium','mcq','Which protein deficiency most commonly underlies hereditary spherocytosis?','["A) Glucose-6-phosphate dehydrogenase deficiency reducing NADPH production", "B) Spectrin or ankyrin mutations weakening the red cell membrane skeleton", "C) Pyruvate kinase deficiency reducing red cell ATP", "D) Haemoglobin S polymerisation causing membrane rigidity"]','B','Hereditary spherocytosis is caused by mutations affecting membrane skeletal proteins, most commonly ankyrin, band 3, spectrin (alpha or beta), or band 4.2. These mutations weaken the tethering interactions that stabilise the lipid bilayer, causing membrane fragments to be shed and forcing the cell to adopt a spherical shape.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','medium','mcq','A 10-year-old boy presents with sudden anaemia 3 days after eating fava beans. Blood film shows red cells appearing to have a bite taken from them. What is the diagnosis?','["A) Hereditary spherocytosis with aplastic crisis", "B) Autoimmune haemolytic anaemia triggered by dietary antigens", "C) G6PD deficiency with oxidative haemolysis and formation of bite cells and Heinz bodies", "D) Sickle cell disease with vaso-occlusive crisis"]','C','G6PD deficiency causes episodic oxidative haemolysis triggered by fava beans, infections, or drugs. Oxidants denature haemoglobin to form Heinz bodies; macrophages pluck these out leaving bite cells. Because older red cells have lower G6PD activity, the haemolysis is self-limited once young G6PD-replete cells predominate.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','easy','mcq','G6PD deficiency is inherited in which pattern?','["A) Autosomal dominant", "B) Autosomal recessive", "C) Mitochondrial inheritance", "D) X-linked recessive"]','D','G6PD deficiency is an X-linked recessive disorder, placing males at higher risk for clinically significant haemolysis. The most clinically significant variants are G6PD- (prevalent in African Americans) and G6PD Mediterranean. The high frequency of these variants is due to protection against Plasmodium falciparum malaria.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','medium','mcq','In warm autoimmune haemolytic anaemia (AIHA), which immunoglobulin class typically mediates red cell destruction?','["A) IgG, opsonising red cells for splenic macrophage destruction", "B) IgM, causing complement-mediated intravascular lysis", "C) IgA, activating the alternative complement pathway", "D) IgE, triggering mast cell degranulation and red cell lysis"]','A','Warm AIHA is characterised by IgG antibodies (active at 37 degrees C) that bind red cell antigens, opsonising them for recognition by IgG Fc receptors on macrophages, predominantly in the spleen. This leads to extravascular haemolysis. Cold AIHA is mediated by IgM, which activates complement and can cause intravascular haemolysis.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','hard','mcq','Which laboratory finding most reliably differentiates intravascular from extravascular haemolysis?','["A) Elevated unconjugated bilirubin is present in intravascular but not extravascular haemolysis", "B) Haemoglobinaemia and haemoglobinuria occur in intravascular haemolysis; splenomegaly occurs only in extravascular haemolysis", "C) Reticulocytosis is found only in intravascular haemolysis", "D) Elevated LDH is specific to extravascular haemolysis"]','B','Both types cause elevated unconjugated bilirubin, reticulocytosis, and depleted haptoglobin. Intravascular haemolysis uniquely produces haemoglobinaemia, haemoglobinuria (giving urine a red-brown colour), and haemosiderinuria. Splenomegaly is prominent in extravascular but not intravascular haemolysis.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','hard','mcq','In hereditary spherocytosis, why does splenectomy correct the anaemia even though spherocytes persist in the circulation afterwards?','["A) Splenectomy removes the source of anti-red cell autoantibodies", "B) Splenectomy eliminates the erythrostasis environment that depletes red cell glucose", "C) The spleen is the primary site of spherocyte sequestration and macrophage-mediated destruction; removing it allows spherocytes to survive longer in the circulation", "D) Post-splenectomy thrombocytosis compensates for anaemia by improving haemostasis"]','C','Spherocytes lack the deformability needed to traverse the narrow splenic sinusoids and become trapped in the cords of Billroth, where they are phagocytosed. After splenectomy, spherocytes persist but can circulate freely without being destroyed. The anaemia is thus corrected, although the underlying membrane defect remains.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','medium','mcq','A child with hereditary spherocytosis develops sudden worsening of anaemia following a viral illness without jaundice. What is the most likely mechanism?','["A) Autoimmune haemolytic crisis triggered by viral antibodies cross-reacting with red cell antigens", "B) Folate deficiency developing secondary to increased erythropoiesis", "C) Sequestration crisis with massive splenic trapping of sickled cells", "D) Aplastic crisis caused by parvovirus B19 infecting and killing erythroid progenitors"]','D','Parvovirus B19 infects erythroid progenitors and transiently abolishes erythropoiesis for 1-2 weeks. In patients with haemolytic anaemia whose red cell lifespan is already shortened to 10-20 days, even brief cessation of production causes a precipitous fall in haemoglobin — the aplastic crisis.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','easy','mcq','Pigment gallstones in a patient with chronic haemolytic anaemia form due to which mechanism?','["A) Excess unconjugated bilirubin excreted in bile promotes calcium bilirubinate stone formation", "B) Cholesterol supersaturation from impaired bile acid synthesis", "C) Elevated conjugated bilirubin from hepatic overload precipitating in bile", "D) Iron deposition in the gallbladder wall from haemosiderosis"]','A','In chronic haemolytic anaemias, increased haemoglobin catabolism produces large amounts of unconjugated bilirubin. Excessive excretion of bilirubin in bile leads to increased formation of calcium bilirubinate (pigment) gallstones. Cholelithiasis occurs in 40-50% of adults with hereditary spherocytosis.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','medium','mcq','Paroxysmal nocturnal haemoglobinuria (PNH) is caused by somatic mutations in which gene, leading to complement-mediated haemolysis?','["A) CD59 directly, causing loss of membrane inhibitor of reactive lysis", "B) PIGA, an enzyme required for GPI-anchor synthesis, causing deficiency of complement regulatory proteins CD55 and CD59 on blood cells", "C) Complement factor H gene, impairing alternative pathway regulation", "D) HBA1/HBA2, causing alpha-globin chain excess and membrane instability"]','B','PNH results from acquired somatic mutations in PIGA, an X-linked gene encoding a GPI-anchor biosynthetic enzyme. Loss of PIGA causes deficiency of GPI-linked complement regulatory proteins (CD55 and CD59) on haematopoietic cells, rendering them susceptible to complement-mediated intravascular haemolysis.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','easy','mcq','What is the molecular defect underlying sickle cell disease?','["A) Deletion of two alpha-globin genes on the same chromosome", "B) A point mutation in the sixth codon of alpha-globin replacing lysine with glutamate", "C) A point mutation in the sixth codon of beta-globin replacing glutamate with valine", "D) A frameshift mutation in HBB creating a premature stop codon"]','C','Sickle cell disease is caused by a point mutation in the sixth codon of the beta-globin gene (HBB), substituting valine for glutamate. This single amino acid change produces HbS, which polymerises upon deoxygenation, distorting the red cell into a sickle shape and causing the downstream pathology.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','medium','mcq','Which factor most strongly inhibits HbS polymerisation, explaining why infants do not manifest sickle cell disease until 5-6 months of age?','["A) High concentration of HbA2 in fetal red cells", "B) High oxygen tension in neonatal blood preventing deoxygenation", "C) Smaller red cell size in infancy reducing intracellular HbS concentration", "D) High levels of fetal haemoglobin (HbF; alpha2gamma2) which inhibit HbS polymerisation"]','D','HbF (fetal haemoglobin, alpha2gamma2) is a potent inhibitor of HbS polymerisation — more so than HbA. Infants are protected from sickling while HbF predominates in the first months of life. As HbF is replaced by HbS after 5-6 months, clinical manifestations emerge. This also explains why hydroxyurea (which raises HbF) is therapeutic.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','medium','mcq','A 20-year-old man with sickle cell disease develops sudden severe chest pain, fever, cough, and new pulmonary infiltrates. What is the most likely diagnosis?','["A) Acute chest syndrome — a vaso-occlusive crisis involving the pulmonary vasculature", "B) Community-acquired pneumococcal pneumonia", "C) Pulmonary embolism from deep venous thrombosis", "D) Sickle cell-related pulmonary hypertension with acute decompensation"]','A','Acute chest syndrome is a particularly dangerous vaso-occlusive crisis involving the lungs, presenting with fever, cough, chest pain, and pulmonary infiltrates. Pulmonary inflammation creates a low-oxygen environment that worsens sickling and vaso-occlusion, potentially creating a fatal cycle of worsening pulmonary and systemic hypoxaemia.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','medium','mcq','Why do patients with sickle cell disease develop autosplenectomy?','["A) Anti-splenic antibodies develop secondary to chronic haemolysis destroying the splenic parenchyma", "B) Repeated vaso-occlusive episodes in the splenic vasculature cause progressive infarction, fibrosis, and shrinkage", "C) Iron overload from transfusions deposits in the spleen causing sclerosis", "D) Extramedullary haematopoiesis in the spleen leads to fibrosis and functional failure"]','B','In sickle cell disease, the spleen is initially enlarged due to red pulp congestion from trapped sickled cells. Over time, chronic erythrostasis leads to repeated splenic infarction and progressive fibrosis, so that by adolescence only a small fibrous remnant remains. This autosplenectomy leaves patients vulnerable to encapsulated organisms.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','easy','mcq','What percentage of African Americans are heterozygous carriers of the HbS mutation (sickle cell trait)?','["A) About 1-2%", "B) About 20-25%", "C) About 8-10%", "D) About 30-35%"]','C','Approximately 8-10% of African Americans are heterozygous for HbS (sickle cell trait). These individuals carry one normal HbA allele and one HbS allele; about 40% of their haemoglobin is HbS. They are largely asymptomatic because HbA interferes with HbS polymerisation except under conditions of extreme hypoxia.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','hard','mcq','Which mechanism explains how HbS mutations have been maintained at high frequency in malaria-endemic regions?','["A) HbS heterozygotes have improved oxygen delivery to tissues, providing a selective growth advantage", "B) HbS induces G6PD upregulation in all carriers, enhancing oxidant protection", "C) HbS binds Plasmodium falciparum merozoites, preventing erythrocyte invasion", "D) HbS promotes sickling in parasitised red cells, enhancing splenic clearance and reducing PfEMP-1 mediated cytoadherence"]','D','In sickle cell trait (HbAS), metabolically active parasites promote sickling in infected red cells. These distorted cells are cleared more rapidly by the spleen. Additionally, sickling impairs formation of membrane knobs displaying PfEMP-1, which mediate cytoadherence of infected cells to endothelium — a key mechanism in cerebral malaria pathogenesis.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','medium','mcq','What peripheral blood findings on smear are most characteristic of sickle cell disease?','["A) Irreversibly sickled cells along with target cells, Howell-Jolly bodies, and reticulocytosis", "B) Target cells alone", "C) Howell-Jolly bodies alone", "D) Pencil cells and microcytosis"]','A','The peripheral blood smear in sickle cell disease shows irreversibly sickled cells (even when fully oxygenated), target cells (from red cell dehydration), Howell-Jolly bodies (nuclear remnants from functional asplenia), and reticulocytosis from compensatory erythropoiesis. The combination is highly characteristic.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','hard','mcq','A patient is compound heterozygous for HbS and HbC. How does HbSC disease differ from homozygous sickle cell disease (HbSS)?','["A) HbSC is more severe because HbC augments HbS polymerisation more than HbA", "B) HbSC disease is clinically milder than HbSS because HbS is only 50% and HbC causes less polymerisation than HbS alone", "C) HbSC is identical in severity to HbSS because both have 100% abnormal haemoglobin", "D) HbSC disease has no clinical manifestations because HbC fully inhibits HbS polymerisation"]','B','In HbSC disease, 50% of haemoglobin is HbS and 50% is HbC. Although HbSC cells lose water and become dehydrated (increasing HbS concentration and polymerisation risk), the clinical syndrome is milder than HbSS. Patients have sickling complications but at reduced severity compared to homozygous disease.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','medium','mcq','Which drug reduces vaso-occlusive crises in sickle cell disease by increasing levels of fetal haemoglobin?','["A) Desferrioxamine", "B) Deferoxamine", "C) Hydroxyurea", "D) L-glutamine"]','C','Hydroxyurea, an inhibitor of DNA synthesis, increases HbF levels in sickle cell disease through uncertain mechanisms. Elevated HbF inhibits HbS polymerisation. Hydroxyurea also has anti-inflammatory effects by reducing leukocyte production. Together, these effects decrease the frequency of vaso-occlusive crises.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','easy','mcq','Children with sickle cell disease are at increased risk of sepsis from which type of organism, due to functional asplenia?','["A) Gram-negative enteric bacteria such as Escherichia coli", "B) Fungal infections with Candida and Aspergillus species", "C) Intracellular organisms such as Mycobacterium tuberculosis", "D) Encapsulated bacteria including Streptococcus pneumoniae and Haemophilus influenzae"]','D','Autosplenectomy renders sickle cell patients functionally asplenic, impairing clearance of encapsulated bacteria such as Streptococcus pneumoniae and Haemophilus influenzae that evade phagocytosis without adequate opsonisation. Pneumococcal meningitis and septicaemia are common and can be life-threatening; prophylactic antibiotics and vaccination are essential.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','easy','mcq','Beta-thalassaemia major presents clinically when haemoglobin synthesis switches from fetal to adult haemoglobin. At what age does this typically occur?','["A) At 6-9 months of age", "B) At birth", "C) At 2-3 years of age", "D) At 5-6 years of age"]','A','Beta-thalassaemia major presents clinically at 6-9 months of age, when the haematopoietic switch from HbF to HbA production is largely complete. Until this point, fetal haemoglobin compensates for the deficient beta-globin synthesis and patients are relatively protected.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','medium','mcq','Which finding on haemoglobin electrophoresis most reliably distinguishes beta-thalassaemia minor (trait) from iron deficiency anaemia?','["A) Elevated HbF above 50% of total haemoglobin", "B) Elevated HbA2 (alpha2delta2) to 4-8% of total haemoglobin", "C) Absent HbA with predominance of HbH", "D) Presence of HbS on electrophoresis"]','B','Beta-thalassaemia minor (trait) is characterised by an elevated HbA2 level of 4-8% (normal 2.5 +/- 0.3%), reflecting an elevated ratio of delta-chain to beta-chain synthesis. This distinguishes it from iron deficiency anaemia, which also causes microcytic hypochromic anaemia but without elevated HbA2.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','medium','mcq','Hydrops fetalis in alpha-thalassaemia is caused by deletion of all four alpha-globin genes. What tetrameric haemoglobin predominates in these fetuses?','["A) HbH (beta4 tetramers)", "B) HbA2 (alpha2delta2)", "C) Haemoglobin Barts (gamma4 tetramers)", "D) HbF (alpha2gamma2)"]','C','When all four alpha-globin genes are deleted, excess gamma chains form gamma4 tetramers known as haemoglobin Barts. HbBarts has an extremely high oxygen affinity and delivers virtually no oxygen to tissues, causing severe anoxia, hydrops fetalis (generalised oedema), and death in utero or shortly after birth.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','easy','mcq','What is the primary mechanism by which unpaired alpha-globin chains cause anaemia in beta-thalassaemia major?','["A) Alpha chains directly inhibit haem synthesis, causing iron accumulation", "B) Free alpha chains activate the complement cascade causing intravascular haemolysis", "C) Alpha chains competitively bind haem groups, preventing HbF production", "D) Excess alpha chains precipitate in erythroid precursors forming insoluble inclusions that damage membranes, leading to ineffective erythropoiesis and haemolysis"]','D','In beta-thalassaemia, unpaired alpha chains precipitate within erythroid precursors forming insoluble inclusions. These inclusions damage cell membranes, causing up to 70-85% of erythroid precursors to undergo apoptosis in the marrow (ineffective erythropoiesis). Cells that escape are prone to splenic sequestration and extravascular haemolysis.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','hard','mcq','An X-ray of the skull in a child with untransfused beta-thalassaemia major shows crewcut periosteal new bone formation. What is the pathological basis?','["A) Marrow expansion from massive erythroid hyperplasia eroding cortical bone and inducing new bone formation", "B) Chronic osteomyelitis from encapsulated organism infections secondary to splenic dysfunction", "C) Iron deposition in the skull from transfusion-related haemosiderosis", "D) Extramedullary haematopoiesis producing intracranial mass lesions"]','A','Profound anaemia in beta-thalassaemia major drives intense erythropoietin-mediated erythroid hyperplasia. The burgeoning marrow expands into the bony cortex, eroding it and stimulating new bone formation perpendicular to the cortical surface, producing the crewcut or hair-on-end appearance on skull X-ray and characteristic facial bossing.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','medium','mcq','Why do patients with beta-thalassaemia major develop secondary haemochromatosis even without blood transfusions?','["A) Beta-globin gene mutations directly disrupt iron metabolism pathways", "B) Ineffective erythropoiesis suppresses hepcidin production, increasing intestinal iron absorption despite elevated iron stores", "C) Haemolysis releases large amounts of free haem which is reutilised as dietary iron", "D) Abnormal red cell membrane proteins cause iron to leak out of storage proteins"]','B','Ineffective erythropoiesis in beta-thalassaemia suppresses hepatic hepcidin production even when iron stores are elevated. Low hepcidin increases ferroportin activity, allowing excessive iron absorption from the gut. Combined with transfusion-related iron loading, this leads to severe secondary haemochromatosis damaging the liver, heart, and endocrine organs.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','easy','mcq','How many alpha-globin genes does a normal individual have?','["A) Two, one per chromosome 16", "B) Two, one per chromosome 11", "C) Four, two per chromosome 16", "D) Four, two per chromosome 11"]','C','Humans normally have four alpha-globin genes, arranged as two genes (HBA1 and HBA2) on each copy of chromosome 16. The severity of alpha-thalassaemia depends on how many of these four genes are deleted or non-functional, ranging from silent carrier state (one gene deleted) to hydrops fetalis (all four deleted).','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','medium','mcq','HbH disease results from deletion of three alpha-globin genes. Which haemoglobin forms and why is it clinically problematic?','["A) HbA2 (alpha2delta2) is the predominant haemoglobin, causing clinical disease from delta-chain excess", "B) Haemoglobin Barts (gamma4) forms and delivers oxygen efficiently unlike in adults", "C) HbF levels rise compensatorily and normalise oxygen delivery", "D) HbH (beta4 tetramers) forms because excess beta chains cannot be incorporated into HbA; it has high oxygen affinity and is prone to oxidative precipitation"]','D','With only one functional alpha-globin gene, alpha chain production is severely reduced and excess beta chains form HbH (beta4 tetramers). HbH has an extremely high oxygen affinity (not useful for tissue oxygen delivery) and is prone to oxidative damage, precipitating as inclusions that lead to haemolysis and cause moderately severe anaemia.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','hard','mcq','A patient with beta-thalassaemia major who also has coexistent alpha-thalassaemia has a milder clinical course. Why?','["A) Alpha-thalassaemia reduces alpha-globin synthesis, lessening the imbalance between alpha and beta chains and reducing inclusion body formation", "B) Alpha-thalassaemia increases HbF production, compensating for beta-globin deficiency", "C) Alpha-thalassaemia mutations repair the beta-globin reading frame through intergenic recombination", "D) Coexistent alpha-thalassaemia reduces total haemoglobin synthesis, decreasing red cell oxygen demand"]','A','The main cause of red cell pathology in beta-thalassaemia is the excess of unpaired alpha chains that precipitate as inclusions. Coexistent alpha-thalassaemia reduces total alpha-chain synthesis, lessening the imbalance between alpha and beta chains. This reduces inclusion body formation and improves the effectiveness of erythropoiesis, resulting in milder disease.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','medium','mcq','Which of the following blood film findings is most characteristic of beta-thalassaemia major?','["A) Macrocytic oval red cells with hypersegmented neutrophils", "B) Microcytic hypochromic red cells with target cells, basophilic stippling, and nucleated red cell precursors", "C) Spherocytes and polychromasia without target cells", "D) Irreversibly sickled cells with Howell-Jolly bodies"]','B','The blood smear in beta-thalassaemia major shows severe red cell abnormalities including marked anisocytosis, poikilocytosis, microcytosis, and hypochromia. Target cells, basophilic stippling, and nucleated red cell precursors (normoblasts) from extramedullary haematopoiesis are also characteristic.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','easy','mcq','Which leukaemia is most common in children and is associated with the t(12;21) ETV6-RUNX1 translocation carrying a favourable prognosis?','["A) Acute myeloid leukaemia (AML)", "B) Chronic myeloid leukaemia (CML)", "C) B-cell acute lymphoblastic leukaemia (B-ALL)", "D) Chronic lymphocytic leukaemia (CLL)"]','C','Acute lymphoblastic leukaemia (ALL) is the most common cancer of children, with B-ALL comprising about 85% of cases. The t(12;21) translocation involving ETV6 and RUNX1 is one of the most common chromosomal aberrations in childhood B-ALL and confers a favourable prognosis with chemotherapy.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','medium','mcq','The Philadelphia chromosome t(9;22) in chronic myeloid leukaemia (CML) creates which chimeric oncogene?','["A) MYC-IGH fusion gene with constitutive MYC transcription", "B) ETV6-RUNX1 fusion gene preventing B-cell maturation", "C) PML-RARA fusion gene blocking myeloid differentiation", "D) BCR-ABL fusion gene encoding a constitutively active tyrosine kinase"]','D','The t(9;22) Philadelphia chromosome creates the BCR-ABL fusion gene, encoding a constitutively active BCR-ABL tyrosine kinase. This kinase activates proliferative and anti-apoptotic signalling pathways independent of normal growth factor control. Imatinib and other BCR-ABL tyrosine kinase inhibitors have transformed CML from a fatal disease to a manageable chronic condition.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','medium','mcq','Acute promyelocytic leukaemia (APML) carries the t(15;17) translocation. Why does treatment with all-trans retinoic acid (ATRA) work?','["A) The PML-RARA fusion protein blocks myeloid differentiation at the promyelocyte stage; ATRA targets RARA to relieve the differentiation block, inducing maturation", "B) ATRA inhibits BCR-ABL tyrosine kinase activity", "C) ATRA activates caspase-mediated apoptosis in leukaemic promyelocytes", "D) ATRA upregulates CD20 expression, allowing rituximab to destroy leukaemic cells"]','A','The t(15;17) translocation produces PML-RARA, a fusion protein that acts as a dominant negative inhibitor of the retinoic acid receptor alpha, blocking myeloid differentiation at the promyelocyte stage. Pharmacological doses of ATRA overcome this block by promoting differentiation of leukaemic promyelocytes into mature granulocytes, curing over 80% of patients.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','medium','mcq','A 65-year-old man presents with peripheral lymphocytosis of 80x10^9/L, composed of small mature-looking lymphocytes with condensed chromatin. Blood film shows smudge cells. What is the most likely diagnosis?','["A) Acute lymphoblastic leukaemia (ALL)", "B) Chronic lymphocytic leukaemia (CLL)", "C) Hairy cell leukaemia", "D) Adult T-cell leukaemia/lymphoma (ATLL)"]','B','CLL is the most common leukaemia of adults and is characterised by accumulation of small, mature-appearing CD5+ B cells with condensed chromatin. Smudge cells (fragile lymphocytes crushed during smear preparation) are characteristic. CLL typically pursues an indolent course with bone marrow involvement and lymphadenopathy.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','hard','mcq','Which cytogenetic abnormality in AML is associated with the best prognosis when treated with conventional chemotherapy?','["A) Monosomy 5 or 7", "B) Complex karyotype with multiple chromosomal losses", "C) t(8;21) or inv(16)", "D) t(9;22) Philadelphia chromosome"]','C','AMLs with t(8;21)(q22;q22) or inv(16)(p13;q22) have core binding factor (CBF) involvement and are associated with relatively good outcomes with conventional chemotherapy, with complete remission rates exceeding 90%. In contrast, monosomy 5 or 7, complex karyotypes, and secondary AML following MDS carry poor prognoses.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','medium','mcq','A patient presents with bone marrow failure, circulating blasts comprising 30% of marrow cells, and Auer rods on blood film. What is the diagnosis?','["A) Myelodysplastic syndrome", "B) B-cell acute lymphoblastic leukaemia", "C) Chronic myeloid leukaemia in blast crisis", "D) Acute myeloid leukaemia (AML)"]','D','Auer rods are elongated azurophilic crystalline inclusions unique to the myeloid lineage and are pathognomonic of AML. The presence of 20% or more blasts in the bone marrow is diagnostic of AML. AML presents with bone marrow failure causing anaemia, neutropenia, and thrombocytopenia.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','easy','mcq','T-ALL most commonly presents in which demographic?','["A) Adolescent males, often as a mediastinal (thymic) mass", "B) Elderly women with lymph node enlargement", "C) Young children under 5 years with bone marrow failure", "D) Middle-aged adults with splenomegaly and monocytosis"]','A','T-ALL accounts for about 15% of ALL cases and typically presents in adolescent males as a thymic mass. The thymus is the predominant site of T-cell development and reaches maximum size during adolescence. Clinical presentations may include mediastinal widening with or without superior vena cava compression.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','hard','mcq','In B-ALL, the presence of a BCR-ABL fusion gene with higher kinase activity than that found in CML carries which clinical implication?','["A) A more indolent course requiring less intensive chemotherapy", "B) A worse prognosis that requires incorporation of BCR-ABL tyrosine kinase inhibitors for effective treatment", "C) A good prognosis equivalent to t(12;21)-positive ALL", "D) Spontaneous remission without chemotherapy"]','B','In B-ALL, the BCR-ABL1 fusion encodes a kinase with higher activity than the version found in CML. This correlates with a poor prognosis compared to other B-ALL subtypes. The addition of BCR-ABL tyrosine kinase inhibitors (e.g., imatinib or dasatinib) to chemotherapy has significantly improved outcomes for t(9;22)-positive B-ALL.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','medium','mcq','CML is distinguished from other myeloproliferative disorders by which specific molecular finding?','["A) JAK2 V617F point mutation in over 95% of cases", "B) KIT point mutation causing constitutive stem cell factor receptor activation", "C) BCR-ABL chimeric gene from the t(9;22) Philadelphia chromosome translocation", "D) FIP1L1-PDGFRA fusion from chromosome 4q12 deletion"]','C','All cases of CML harbour the BCR-ABL1 fusion gene generated by the t(9;22)(q34;q11) Philadelphia chromosome translocation. This is the defining molecular feature of CML and distinguishes it from other myeloproliferative neoplasms such as polycythaemia vera, essential thrombocythaemia, and primary myelofibrosis, which are associated with JAK2 mutations.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','medium','mcq','A 70-year-old man with CLL develops sudden worsening with rapidly enlarging lymph nodes, elevated LDH, and new constitutional symptoms. Biopsy shows large transformed B cells. What has occurred?','["A) Transformation to AML (myeloid blast crisis)", "B) Drug-induced immunoblastic lymphadenopathy", "C) Development of hairy cell leukaemia", "D) Richter transformation — evolution of CLL to diffuse large B-cell lymphoma (DLBCL)"]','D','Richter syndrome (Richter transformation) occurs in about 5% of CLL patients and represents transformation of CLL to an aggressive large B-cell lymphoma (typically DLBCL), heralded by rapid lymph node enlargement, rising LDH, and constitutional symptoms. It carries a very poor prognosis with median survival of months.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','easy','mcq','Which cell is the neoplastic cell of Hodgkin lymphoma, and what are its two most essential immunohistochemical markers in classical HL?','["A) Reed-Sternberg cell expressing CD15 and CD30", "B) Centroblast expressing CD20 and CD10", "C) Mantle cell expressing cyclin D1 and CD5", "D) Plasma cell expressing CD138 and cytoplasmic immunoglobulin"]','A','The neoplastic cell of classical Hodgkin lymphoma is the Reed-Sternberg cell — a large cell with bilobed or multilobed nuclei and prominent owl-eye nucleoli. Reed-Sternberg cells in classical HL are characteristically CD15+ and CD30+, while lacking expression of most B-cell markers and CD45.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','medium','mcq','What is the most common subtype of Hodgkin lymphoma, and which anatomical site does it most typically involve?','["A) Mixed cellularity type, most commonly involving mesenteric lymph nodes", "B) Nodular sclerosis type, most commonly involving lower cervical, supraclavicular, and mediastinal lymph nodes", "C) Lymphocyte-rich type, most commonly involving the liver and bone marrow", "D) Lymphocyte depletion type, most commonly involving the spleen and peripheral blood"]','B','Nodular sclerosis is the most common subtype of HL, comprising 65-70% of cases. It characteristically involves the mediastinum and lower cervical/supraclavicular nodes in adolescents and young adults. It features lacunar variant Reed-Sternberg cells surrounded by collagen bands dividing the node into nodules.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','medium','mcq','Burkitt lymphoma is characterised by translocation of MYC to an immunoglobulin gene locus. What is the most common translocation?','["A) t(14;18) juxtaposing MYC to IgH", "B) t(8;22) juxtaposing MYC with the IgL lambda locus", "C) t(8;14) juxtaposing MYC with the IgH locus on chromosome 14", "D) t(11;14) juxtaposing MYC with cyclin D1"]','C','Burkitt lymphoma is driven by deregulated MYC expression, most commonly through t(8;14) translocation placing MYC (chromosome 8q24) adjacent to the IgH gene (14q32). Less commonly, MYC is translocated to the kappa or lambda light-chain loci. MYC is a major transcriptional activator of cell growth and proliferation.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','medium','mcq','A lymph node biopsy from a patient with Burkitt lymphoma shows a starry sky pattern. What does this pattern represent?','["A) Scattered plasma cells among small lymphocytes mimicking starlight", "B) Lacunar Reed-Sternberg cells surrounded by fibrous bands mimicking a night sky", "C) Follicular pattern with pale germinal centres amid dark mantle zones", "D) Scattered pale macrophages containing apoptotic tumour cell debris (tingible body macrophages) among sheets of dark lymphoma cells"]','D','The starry sky pattern in Burkitt lymphoma is created by scattered pale tingible body macrophages (containing phagocytosed apoptotic debris from rapidly dividing and dying tumour cells) against a dark background of densely packed, monotonous medium-sized lymphoma cells. This pattern reflects the extremely high proliferative and apoptotic rate.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','easy','mcq','Follicular lymphoma is most strongly associated with which chromosomal translocation?','["A) t(14;18) causing BCL2 overexpression", "B) t(8;14) causing MYC overexpression", "C) t(11;14) causing cyclin D1 overexpression", "D) t(9;22) causing BCR-ABL kinase activation"]','A','The t(14;18)(q32;q21) translocation is found in up to 90% of follicular lymphomas. It juxtaposes the BCL2 gene (chromosome 18) with the IgH gene (chromosome 14), resulting in constitutive overexpression of BCL2, an anti-apoptotic protein. This allows follicular lymphoma cells to survive indefinitely despite lacking a survival stimulus.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','hard','mcq','EBV is found in what proportion of classical Hodgkin lymphoma cases, and how is it thought to contribute to Reed-Sternberg cell formation?','["A) 5% of cases; EBV disrupts B-cell surface marker expression", "B) 30-40% of classical HL cases; EBV LMP-1 activates NF-kB, rescuing crippled germinal centre B cells that cannot express Ig from apoptosis", "C) 100% of cases; EBV directly transforms B cells into Reed-Sternberg cells", "D) 70% of cases; EBV drives hypermutation of BCL6, promoting large cell transformation"]','B','EBV is found in 30-40% of classical Hodgkin lymphoma cases (and up to 70% of the mixed cellularity subtype). EBV-encoded LMP-1 activates NF-kB, which may rescue crippled germinal centre B cells (that have lost functional Ig expression) from apoptosis, providing a survival platform for additional mutations needed to generate Reed-Sternberg cells.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','medium','mcq','Diffuse large B-cell lymphoma (DLBCL) is the most common lymphoma in adults. What proportion of cases carry a t(14;18) BCL2 translocation, suggesting origin from follicular lymphoma?','["A) Less than 5% of DLBCL cases", "B) About two thirds of DLBCL cases", "C) About one third of DLBCL cases", "D) Nearly all DLBCL cases"]','C','Approximately one third of DLBCL cases carry the t(14;18) BCL2 translocation and may arise by transformation from a pre-existing follicular lymphoma. In addition, rearrangements or mutations of BCL6 are common in DLBCL. Despite its heterogeneity, DLBCL is potentially curable with immunochemotherapy (R-CHOP) in about 60-70% of patients.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','medium','mcq','How does Hodgkin lymphoma differ from non-Hodgkin lymphoma in its pattern of spread?','["A) Hodgkin lymphoma spreads haematogenously while NHL spreads via the lymphatics", "B) Hodgkin lymphoma commonly involves extranodal sites early, while NHL remains confined to lymph nodes", "C) Hodgkin lymphoma commonly involves mesenteric nodes and Waldeyer ring, while NHL does not", "D) Hodgkin lymphoma spreads in an orderly, contiguous fashion through adjacent lymph node groups, while NHL spreads non-contiguously and unpredictably"]','D','Hodgkin lymphoma characteristically spreads in an orderly, contiguous fashion from one lymph node group to adjacent groups, making staging by lymph node involvement clinically meaningful for guiding therapy. NHL spreads unpredictably to multiple peripheral nodes and extranodal sites early in the disease course.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','hard','mcq','Endemic Burkitt lymphoma predominantly affects which anatomical site, while sporadic Burkitt lymphoma more often presents where?','["A) Endemic: jaw/facial bones; Sporadic: ileocaecal region, ovaries, or kidneys", "B) Endemic: mediastinum; Sporadic: jaw/face", "C) Endemic: bone marrow; Sporadic: mesenteric lymph nodes", "D) Endemic: nasopharynx; Sporadic: bone marrow"]','A','Endemic Burkitt lymphoma, seen in equatorial Africa in association with malaria and EBV, most commonly involves the jaw and facial bones. Sporadic Burkitt lymphoma, found in non-endemic regions, more often presents as an abdominal mass involving the ileocaecal region, ovaries, or kidneys. Both forms carry MYC translocations.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','medium','mcq','A patient with follicular lymphoma undergoes transformation to an aggressive histology. Which lymphoma does it most commonly transform to?','["A) Burkitt lymphoma with MYC translocation", "B) Diffuse large B-cell lymphoma", "C) Mantle cell lymphoma with cyclin D1 overexpression", "D) T-cell lymphoma through lineage switching"]','B','Follicular lymphoma, an indolent disease, eventually transforms to an aggressive large-cell lymphoma in many patients. The most common histological transformation is to diffuse large B-cell lymphoma. This transformation is associated with acquisition of additional oncogenic mutations such as MYC translocations and is often rapidly fatal.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','easy','mcq','What are the four major clinical features of multiple myeloma summarised by the CRAB criteria?','["A) Cytopenia, Renal failure, Adenopathy, Bleeding", "B) Coagulopathy, Radiculopathy, Anaemia, Bone pain", "C) hyperCalcaemia, Renal insufficiency, Anaemia, Bone lesions", "D) Cryoglobulinaemia, Raised ESR, Amyloidosis, B symptoms"]','C','The CRAB criteria summarise the end-organ damage caused by multiple myeloma: hyperCalcaemia (from osteoclast activation), Renal insufficiency (from Bence Jones proteinuria and hypercalcaemia), Anaemia (from marrow replacement), and Bone lesions (punched-out lytic lesions from RANKL-mediated osteoclast activation without osteoblast response).','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','medium','mcq','What is the nature of the M protein (paraprotein) in most cases of multiple myeloma?','["A) Polyclonal IgM produced by reactive plasma cells", "B) Monoclonal IgM from lymphoplasmacytic differentiation, causing hyperviscosity in all patients", "C) Polyclonal IgG produced in excess by reactive B cells in inflamed bone marrow", "D) Monoclonal immunoglobulin (most commonly IgG) or free light chains produced by the neoplastic plasma cell clone"]','D','Multiple myeloma is characterised by production of a monoclonal immunoglobulin (M protein), most commonly IgG (approximately 55% of patients), followed by IgA (approximately 25%). Bence Jones proteins (free immunoglobulin light chains, either kappa or lambda) are found in urine and are particularly nephrotoxic.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','medium','mcq','A 68-year-old man with multiple myeloma has punched-out skull lesions on X-ray. What cytokine primarily mediates the lytic bone lesions?','["A) Myeloma-derived MIP1alpha upregulating RANKL on stromal cells, leading to osteoclast activation without osteoblast response", "B) IL-6 directly activating osteoclasts through RANKL-independent mechanisms", "C) IL-4 from tumour-associated macrophages activating osteoclastogenesis", "D) TNF-beta from Reed-Sternberg cells in the marrow microenvironment"]','A','Myeloma cells secrete MIP1alpha (macrophage inflammatory protein 1alpha), which upregulates RANKL expression on bone marrow stromal cells. RANKL activates osteoclasts. Simultaneously, myeloma-derived factors inhibit osteoblast function via Wnt pathway modulation, resulting in net bone resorption producing characteristic punched-out lytic lesions.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','easy','mcq','Bence Jones proteins detected in the urine of myeloma patients represent which component?','["A) Intact monoclonal immunoglobulin molecules filtered through damaged glomeruli", "B) Free monoclonal immunoglobulin light chains (kappa or lambda) excreted due to their small molecular size", "C) Fragmented heavy chains from IgG myeloma secreted directly into urine", "D) Albumin excreted due to tubular damage from hypercalcaemia"]','B','Bence Jones proteins are free immunoglobulin light chains (either kappa or lambda) produced in excess by myeloma cells. Because they are small molecules, they are filtered by the glomerulus and excreted in urine. They are directly toxic to renal tubular cells and can form casts, causing myeloma kidney (cast nephropathy).','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','medium','mcq','What histological finding is seen on peripheral blood smear in a patient with a very high M protein level?','["A) Hypersegmented neutrophils from megaloblastic changes", "B) Bite cells and Heinz bodies from oxidative haemolysis", "C) Rouleaux formation — red cells stacked in coin-like linear arrays due to elevated immunoglobulin levels", "D) Sickle cells from haemoglobin polymerisation"]','C','Very high immunoglobulin levels coat red cells and reduce their negative charge, causing them to stack in linear arrays (rouleaux formation) visible on peripheral blood smear. This gives a false elevation in ESR and can interfere with blood grouping. Rouleaux formation is characteristic but not specific to myeloma.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','hard','mcq','Which light-chain isotype in myeloma is most commonly associated with AL amyloidosis?','["A) Kappa light chains, because they are present in more patients with myeloma", "B) IgG heavy chains, which misfold and deposit as amyloid in soft tissues", "C) Both kappa and lambda equally, as amyloidogenicity depends on the M protein quantity", "D) Lambda light chains, particularly from the lambda 6 and lambda 3 families, which are inherently amyloidogenic"]','D','AL amyloidosis results from deposition of amyloidogenic free light chains as beta-pleated sheet fibrils. Lambda light chains, particularly those from the lambda 6 and lambda 3 variable gene families, have structural properties that predispose to amyloid formation. AL amyloidosis can deposit in kidney, heart, liver, nerves, and tongue.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','medium','mcq','Which cytokine is the primary growth and survival factor for myeloma cells and is produced both by tumour cells and bone marrow stromal cells?','["A) Interleukin-6 (IL-6)", "B) Interleukin-4 (IL-4)", "C) Interleukin-2 (IL-2)", "D) Tumour necrosis factor alpha (TNF-alpha)"]','A','IL-6 is the most important growth and survival factor for myeloma cells. It is produced in an autocrine fashion by myeloma cells themselves and by bone marrow stromal cells. Elevated serum IL-6 correlates with active disease and poor prognosis.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','easy','mcq','In multiple myeloma, what percentage of bone marrow cellularity typically consists of plasma cells?','["A) Normal marrow has up to 30% plasma cells; over 30% is required for diagnosis", "B) In myeloma, plasma cells usually constitute more than 30% of marrow cellularity; normal marrow has very few plasma cells", "C) Diagnosis requires 50% plasma cell infiltration of the bone marrow", "D) Bone marrow plasma cell percentage is not used in diagnosis; M protein level alone is sufficient"]','B','In multiple myeloma, plasma cells usually constitute more than 30% of bone marrow cellularity and may completely replace normal elements. Normal bone marrow has very few plasma cells (typically less than 2%). Bone marrow plasma cell percentage, serum/urine M protein, and lytic bone lesions all contribute to diagnosis.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','hard','mcq','A patient with MGUS has a serum M protein of 20 g/L, no lytic lesions, normal renal function, and haemoglobin 130 g/L. What is the annual risk of progression to myeloma?','["A) Approximately 20-25% per year", "B) Less than 0.1% per year — MGUS never progresses to myeloma", "C) Approximately 1% per year, constant over time", "D) Approximately 10% per year for the first 5 years, then zero thereafter"]','C','MGUS (monoclonal gammopathy of undetermined significance) is a pre-malignant condition with a rate of progression to symptomatic plasma cell neoplasm (most often myeloma) of approximately 1% per year, which remains constant over time. Periodic monitoring of serum M protein and Bence Jones protein levels is warranted.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','medium','mcq','Which immunoglobulin heavy-chain class is most commonly produced in multiple myeloma?','["A) IgA in approximately 55% of patients", "B) IgE in approximately 55% of patients", "C) IgM in approximately 55% of patients", "D) IgG in approximately 55% of patients"]','D','Approximately 55% of multiple myeloma patients produce IgG as their monoclonal immunoglobulin, making it the most common M protein class. IgA accounts for about 25% of cases. Myelomas producing IgM, IgD, or IgE are rare. About 20% of patients produce only free light chains without intact immunoglobulin.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','easy','mcq','What is the hallmark morphological finding of myelodysplastic syndrome (MDS) in the bone marrow?','["A) Dysplastic (disordered) maturation affecting erythroid, granulocytic, monocytic, and megakaryocytic lineages with ineffective haematopoiesis", "B) Hypercellular marrow with excess myeloblasts greater than 20% and Auer rods", "C) Hypocellular marrow with predominantly fat cells and absent haematopoiesis", "D) Diffuse infiltration by small lymphocytes with lymphoid nodules replacing marrow"]','A','MDS is characterised by clonal stem cell-derived dysplastic maturation affecting one or more myeloid lineages. Bone marrow is usually hypercellular (paradoxically) despite peripheral blood cytopenias, due to intramedullary apoptosis of abnormal progenitors (ineffective haematopoiesis).','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','medium','mcq','Ringed sideroblasts, a characteristic finding in certain subtypes of MDS, are defined as which of the following?','["A) Erythrocytes with iron-laden macrophage inclusions visible on H&E", "B) Erythroid precursors in which iron-laden mitochondria form a perinuclear ring, visible as blue granules on Prussian blue staining", "C) Mature red cells with cytoplasmic iron deposits forming a ring near the cell membrane", "D) Nucleated red cells with central iron granules from ineffective haem synthesis"]','B','Ringed sideroblasts are erythroid precursors (erythroblasts) in which iron accumulates in mitochondria forming a perinuclear ring of blue granules on Prussian blue staining. They occur when mitochondrial iron utilisation for haem synthesis is impaired. Their presence in more than 15% of erythroblasts defines the RARS subtype of MDS.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','medium','mcq','Which cytogenetic abnormality in MDS is associated with a distinctive clinical syndrome characterised by macrocytic anaemia and a relatively good prognosis?','["A) Trisomy 8", "B) Monosomy 7", "C) Deletion of the long arm of chromosome 5 (del 5q)", "D) Complex karyotype with deletions of chromosomes 5 and 7"]','C','The 5q- syndrome (isolated del 5q) in MDS is associated with macrocytic anaemia with low blast count, hypolobulated megakaryocytes, female predominance, and a relatively good prognosis. The deleted region contains the ribosomal protein gene RPS14, and loss of RPS14 causes ineffective erythropoiesis. Lenalidomide is effective in this subtype.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','easy','mcq','What are the defining characteristics of aplastic anaemia on bone marrow biopsy?','["A) Hypercellular marrow with dysplastic megakaryocytes", "B) Fibrotic marrow with osteosclerosis and dry tap on aspiration", "C) Normal cellularity with diffuse lymphocytic infiltration", "D) Markedly hypocellular marrow replaced predominantly by fat cells with absent or very sparse haematopoiesis"]','D','Aplastic anaemia is defined by bone marrow failure resulting in a markedly hypocellular marrow. Biopsy characteristically shows marrow largely replaced by fat cells with only scattered haematopoietic elements. The normal 40-60% marrow cellularity is reduced to less than 25%. Peripheral pancytopenia results.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','medium','mcq','What is the most likely pathogenesis of acquired aplastic anaemia in most adult patients?','["A) Autoimmune T-cell mediated destruction of haematopoietic stem cells", "B) Paraneoplastic marrow suppression from a distant solid tumour", "C) Somatic mutation of a single stem cell leading to aplastic transformation", "D) Exposure to ionising radiation causing irreversible stem cell DNA damage"]','A','Most cases of acquired aplastic anaemia are believed to result from autoimmune T-cell mediated destruction of haematopoietic stem cells. Evidence includes: response to immunosuppression, oligoclonal expansion of T cells in affected marrow, and frequency of HLA associations. This also explains the close association between aplastic anaemia and PNH.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','hard','mcq','Pseudo-Pelger-Huet cells are a morphological abnormality seen in MDS. What do they represent?','["A) Neutrophils with toxic granulations and Dohle bodies from infection", "B) Neutrophils with only two nuclear lobes instead of the normal three to four, representing dysgranulopoiesis", "C) Giant platelets from dysthrombopoiesis in MDS", "D) Band cells arrested in maturation before nuclear segmentation occurs in AML"]','B','Pseudo-Pelger-Huet cells are abnormal neutrophils in MDS that have only two nuclear lobes (bilobed pince-nez appearance) instead of the normal three to four lobules. This reflects dysgranulopoiesis (abnormal neutrophil maturation). They are a useful diagnostic clue for MDS on peripheral blood smear.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','medium','mcq','MDS is primarily a disease of which age group, and what is the risk of transformation to AML?','["A) Young adults aged 20-40 years; transformation occurs in approximately 80-90% of patients within 1 year", "B) Children and adolescents; transformation to AML rarely occurs", "C) Older adults with mean onset at 70 years; transformation to AML occurs in 10-40% depending on MDS subtype", "D) Middle-aged adults aged 40-60 years; transformation to AML occurs in 5% lifetime risk only"]','C','Primary MDS is predominantly a disease of older adults with a mean age of onset of 70 years. Overall, 10-40% of patients progress to AML; the risk depends on the percentage of marrow blasts, the severity of cytopenias, and the number of cytogenetic abnormalities. Therapy-related MDS has a higher transformation rate.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','hard','mcq','Which genetic mutation is found in approximately 10% of MDS cases, is associated with complex karyotype, and portends a particularly poor prognosis?','["A) JAK2 V617F mutation", "B) CALR exon 9 insertion/deletion mutation", "C) NPM1 frameshift mutation", "D) TP53 loss-of-function mutation"]','D','TP53 loss-of-function mutations occur in approximately 10% of primary MDS cases and correlate strongly with complex karyotype (multiple chromosomal abnormalities). TP53-mutated MDS has a particularly poor prognosis due to genomic instability and rapid progression to AML. It is also enriched in therapy-related MDS following alkylating agent treatment.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','easy','mcq','A patient with MDS presents with pancytopenia, a hypercellular marrow, and 8% blasts. How is this MDS subtype different from aplastic anaemia?','["A) MDS has clonal dysplastic haematopoiesis producing a hypercellular marrow with abnormal cells; aplastic anaemia has hypocellular marrow due to stem cell destruction without dysplastic changes", "B) MDS is distinguished by hypocellular marrow and response to immunosuppression", "C) Both conditions have identical histology and are distinguished only by blast percentage", "D) MDS is defined by absence of all haematopoietic cells, while aplastic anaemia has residual erythropoiesis"]','A','MDS involves a clonal neoplastic stem cell that differentiates abnormally, producing dysplastic cells; the marrow is usually hypercellular. Aplastic anaemia involves destruction of haematopoietic stem cells with resultant marrow hypoplasia replaced by fat. Distinguishing these conditions is critical as their treatments differ radically.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','medium','mcq','Which drug class has shown benefit in MDS by reducing DNA methylation of silenced tumour suppressor genes and improving haematopoiesis?','["A) Tyrosine kinase inhibitors such as imatinib", "B) DNA methyltransferase inhibitors (hypomethylating agents) such as azacitidine and decitabine", "C) Anti-CD20 monoclonal antibodies such as rituximab", "D) Proteasome inhibitors such as bortezomib"]','B','Epigenetic dysregulation, including aberrant DNA methylation of tumour suppressor and differentiation genes, is a key pathogenetic mechanism in MDS. DNA methyltransferase inhibitors (azacitidine, decitabine) hypomethylate DNA, reactivating silenced genes and improving the effectiveness of haematopoiesis and peripheral blood counts in a subset of patients.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','easy','mcq','What is the pathogenesis of chronic immune thrombocytopenic purpura (ITP)?','["A) Complement-mediated lysis of platelets by IgM autoantibodies in the circulation", "B) Thrombin consumption of platelets in widespread microvascular thrombi", "C) IgG autoantibodies targeting platelet membrane glycoproteins IIb-IIIa or Ib-IX, leading to platelet opsonisation and phagocytosis by splenic macrophages", "D) Bone marrow infiltration by lymphoma cells reducing megakaryocyte numbers"]','C','In chronic ITP, autoantibodies (predominantly IgG, in about 80% of patients) target platelet membrane glycoproteins IIb-IIIa or Ib-IX. These IgG-coated platelets are recognised by Fc receptors on splenic macrophages and phagocytosed (extravascular destruction). The spleen is also a source of autoantibodies, explaining why splenectomy is therapeutic.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','medium','mcq','A 30-year-old woman presents with the pentad of fever, thrombocytopenia, microangiopathic haemolytic anaemia, neurological deficits, and renal failure. ADAMTS13 activity is undetectable. What is the diagnosis?','["A) Haemolytic uraemic syndrome (HUS) from E. coli O157:H7", "B) Systemic lupus erythematosus with antiphospholipid syndrome", "C) Disseminated intravascular coagulation (DIC)", "D) Thrombotic thrombocytopenic purpura (TTP)"]','D','TTP is defined by the pentad of fever, thrombocytopenia, microangiopathic haemolytic anaemia (MAHA), transient neurological deficits, and renal failure. It is caused by deficiency of ADAMTS13 (vWF metalloprotease) — either inherited or acquired via autoantibodies — allowing ultra-large vWF multimers to promote platelet microthrombi throughout the microvasculature.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','medium','mcq','Haemophilia A is caused by a deficiency of which clotting factor and follows which inheritance pattern?','["A) Factor VIII deficiency, X-linked recessive", "B) Factor IX deficiency, X-linked recessive", "C) Factor VIII deficiency, autosomal dominant", "D) Factor V deficiency, autosomal recessive"]','A','Haemophilia A is the most common hereditary disease associated with life-threatening bleeding and is caused by mutations in the factor VIII gene. It is X-linked recessive, affecting primarily males. The most severe form results from an inversion of the X chromosome that abolishes factor VIII synthesis. Factor IX deficiency causes Haemophilia B.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','medium','mcq','A patient with DIC has prolonged PT, prolonged PTT, low fibrinogen, elevated D-dimer, and thrombocytopenia. How does TTP differ from DIC in laboratory investigations?','["A) TTP also shows prolonged PT and PTT along with thrombocytopenia", "B) In TTP, PT and PTT are usually normal because coagulation factor consumption is not a primary mechanism", "C) TTP and DIC are identical in laboratory findings", "D) TTP is distinguished by normal D-dimer and elevated fibrinogen"]','B','A critical distinction: DIC involves pathological activation of the coagulation cascade with consumption of coagulation factors, producing prolonged PT, prolonged PTT, low fibrinogen, and elevated D-dimer. In TTP, platelet activation (not coagulation cascade activation) is the primary mechanism; PT and PTT are typically normal.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','hard','mcq','In haemophilia A, which specific coagulation pathway abnormality explains why patients have a prolonged PTT but normal PT?','["A) Factor VIII is part of the common coagulation pathway, so both PT and PTT should be prolonged", "B) Factor VIII deficiency only affects platelet aggregation, prolonging the PTT indirectly through impaired thrombin generation", "C) Factor VIII is a cofactor in the intrinsic (contact activation) pathway, activating factor X via factor IXa; the PTT tests the intrinsic pathway while PT tests the extrinsic pathway which is unaffected", "D) Factor VIII activates factor VII in the extrinsic pathway; a deficiency affects PT but not PTT"]','C','Factor VIII is an essential cofactor for factor IXa in the intrinsic coagulation pathway, which activates factor X. The PTT tests the intrinsic pathway and is prolonged when factor VIII is deficient. The PT tests the extrinsic pathway (tissue factor + factor VII), which is unaffected — hence PT is normal in haemophilia A and B.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','medium','mcq','Typical haemolytic uraemic syndrome (HUS) in children is strongly associated with which pathogen?','["A) Streptococcus pneumoniae via neuraminidase-mediated red cell damage", "B) Neisseria meningitidis via lipopolysaccharide triggering DIC", "C) Staphylococcus aureus via toxic shock syndrome toxin", "D) Escherichia coli O157:H7, which produces Shiga-like toxin that damages endothelial cells, activating platelet aggregation"]','D','Typical (classic) HUS in children follows enteric infection with E. coli O157:H7, which produces Shiga-like toxin. The toxin is absorbed and damages endothelial cells, triggering platelet activation and aggregation particularly in the renal microcirculation. Patients present with bloody diarrhoea followed by microangiopathic haemolytic anaemia, thrombocytopenia, and acute renal failure.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','easy','mcq','Von Willebrand disease is the most common inherited bleeding disorder. What is the primary function of vWF that is impaired in this condition?','["A) vWF promotes platelet adhesion to subendothelial matrix via GpIb-IX on platelets and also stabilises factor VIII in the circulation", "B) vWF activates the intrinsic coagulation pathway by binding factor XII", "C) vWF cross-links fibrin polymers to form a stable clot", "D) vWF activates complement to promote opsonisation of damaged endothelial cells"]','A','Von Willebrand factor (vWF) has two critical functions: (1) it promotes platelet adhesion to exposed subendothelial matrix by bridging between platelet GpIb-IX and collagen, and (2) it stabilises factor VIII in the circulation (extending its half-life from 2.4 to 12 hours). Deficiency of vWF therefore impairs both primary and secondary haemostasis.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','hard','mcq','Heparin-induced thrombocytopenia type II (HIT type II) is paradoxically associated with thrombosis rather than bleeding. What is the pathomechanism?','["A) Heparin directly activates the extrinsic coagulation pathway causing thrombus formation", "B) Antibodies against heparin-platelet factor 4 complexes bind platelets and activate them, triggering platelet aggregation and thrombosis despite low platelet counts", "C) Heparin displaces antithrombin III from thrombin, allowing unrestricted thrombin activity", "D) Type II HIT causes complement-mediated destruction of endothelium, exposing prothrombotic subendothelial matrix"]','B','Type II HIT occurs 5-14 days after heparin exposure. IgG antibodies form against heparin-platelet factor 4 (PF4) complexes. These complexes bind platelet Fc receptors, causing platelet activation and aggregation. The paradoxical result is thrombocytopenia (from platelet consumption) alongside life-threatening venous and arterial thrombosis. Heparin must be stopped immediately.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','medium','mcq','A patient presents with spontaneous bruising, menorrhagia, and epistaxis. Platelet count is normal. PT is normal. PTT is mildly prolonged. Ristocetin cofactor activity is reduced. What is the most likely diagnosis?','["A) Haemophilia A with mild factor VIII deficiency", "B) ITP with anti-platelet antibodies despite normal count", "C) Von Willebrand disease with reduced vWF and secondary reduced factor VIII levels", "D) Haemophilia B with factor IX deficiency"]','C','Reduced ristocetin cofactor activity indicates impaired vWF function. vWF stabilises factor VIII, so vWF deficiency causes a secondary reduction in factor VIII, mildly prolonging the PTT. The normal platelet count with mucosal and skin bleeding (rather than haemarthroses) and normal PT are consistent with Von Willebrand disease.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','medium','mcq','DIC is initiated by which two main pathological mechanisms?','["A) Autoimmune platelet destruction and simultaneous loss of antithrombin III", "B) Complement activation and MAC-mediated lysis of red cells releasing ADP to trigger coagulation", "C) Decreased hepatic production of coagulation factors combined with excessive fibrinolysis", "D) Release of tissue factor or procoagulants into the circulation from damaged tissues, and widespread endothelial injury activating coagulation"]','D','DIC is triggered by: (1) release of tissue factor or other procoagulants into the circulation (e.g., from placenta in obstetric emergencies, trauma, cancer), and (2) widespread endothelial injury (e.g., from sepsis/TNF) that upregulates procoagulant activity and suppresses thrombomodulin. Both mechanisms lead to pathological systemic thrombin generation and consumption of clotting factors and platelets.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','easy','mcq','Which inherited thrombophilia is the most common cause of heritable hypercoagulability in Caucasian populations?','["A) Factor V Leiden mutation (activated protein C resistance)", "B) Antithrombin III deficiency", "C) Protein C deficiency", "D) Prothrombin G20210A mutation"]','A','Factor V Leiden (a point mutation in the factor V gene rendering factor Va resistant to proteolytic inactivation by activated protein C) is the most common inherited thrombophilic disorder, found in approximately 5% of the general Caucasian population and in a much higher proportion of patients with unexplained venous thromboembolism.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','medium','mcq','What is the primary source of pulmonary emboli in the vast majority of cases?','["A) Upper extremity deep vein thrombosis", "B) Thrombi in the deep veins of the legs", "C) Right atrial thrombi from atrial fibrillation", "D) Intracardiac mural thrombi from myocardial infarction"]','B','Over 95% of pulmonary emboli arise from thrombi in the deep veins of the legs (deep vein thrombosis, DVT), particularly from the popliteal and iliofemoral veins. The deep venous system of the lower extremity drains via the inferior vena cava to the right heart and then into the pulmonary vasculature.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','medium','mcq','The prothrombin G20210A mutation causes thrombophilia by which mechanism?','["A) Preventing prothrombin from being converted to thrombin by factor Xa", "B) Directly inhibiting antithrombin III, preventing thrombin neutralisation", "C) Causing a gain-of-function variant that increases plasma prothrombin levels, augmenting thrombin generation", "D) Creating a constitutively active thrombin molecule that is resistant to antithrombin III"]','C','The prothrombin G20210A mutation is a gain-of-function variant in the 3-prime untranslated region of the prothrombin gene that increases mRNA stability and leads to elevated plasma prothrombin levels (by approximately 30%). Higher prothrombin concentrations provide more substrate for thrombin generation, increasing thrombotic risk.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','medium','mcq','Antiphospholipid syndrome (APS) is characterised by which clinical and laboratory features?','["A) Hereditary deficiency of protein C associated with venous thrombosis in young adults", "B) Anti-platelet antibodies causing thrombocytopenia associated with arterial and venous thrombosis", "C) Factor VIII inhibitor antibodies causing acquired haemophilia with arterial thrombosis", "D) Acquired autoantibodies (lupus anticoagulant, anti-cardiolipin, anti-beta2-glycoprotein I) associated with arterial and venous thrombosis and recurrent pregnancy loss"]','D','APS is an acquired thrombophilia caused by autoantibodies directed against phospholipid-binding proteins (particularly beta2-glycoprotein I). Clinical features include arterial and/or venous thrombosis, thrombocytopenia, and recurrent fetal loss (particularly second-trimester loss). APS may be primary or secondary (e.g., associated with SLE).','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','easy','mcq','What is Virchow''''s triad, which predisposes to venous thromboembolism?','["A) Endothelial injury, stasis of blood flow, and hypercoagulability (alterations in blood constituents)", "B) Thrombocytosis, polycythaemia, and hyperfibrinogenaemia", "C) Elevated LDL, hypertension, and smoking (cardiovascular risk factors)", "D) Immobility, obesity, and malignancy (only secondary risk factors)"]','A','Virchow''''s triad describes the three fundamental causes of thrombosis: (1) endothelial injury exposing subendothelial matrix, (2) stasis or turbulent blood flow reducing clearance of activated clotting factors, and (3) hypercoagulability from inherited or acquired thrombophilic states or elevated procoagulant proteins.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','hard','mcq','A massive saddle pulmonary embolus is found at autopsy. Which immediate haemodynamic consequence most commonly causes sudden death?','["A) Infarction of the left ventricle from coronary hypoperfusion", "B) Acute right heart failure (acute cor pulmonale) from sudden obstruction of pulmonary blood flow causing massive increase in right ventricular afterload", "C) Systemic hypoxia from loss of alveolar ventilation", "D) Paradoxical embolism through a patent foramen ovale causing cerebral infarction"]','B','A massive pulmonary embolus blocking blood flow through the main pulmonary arteries causes sudden, dramatic increases in right ventricular afterload. The right ventricle, not adapted to high afterload, acutely fails (acute cor pulmonale). This results in circulatory collapse and electromechanical dissociation, and sudden death.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','medium','mcq','Which secondary risk factor for VTE is particularly important to consider in a woman presenting with a first DVT at age 40?','["A) G6PD deficiency causing increased red cell rigidity", "B) Anaemia of chronic disease causing compensatory polycythaemia", "C) Use of combined oral contraceptive pill (COCP), which increases hepatic synthesis of clotting factors and reduces protein S", "D) MGUS with elevated immunoglobulin levels promoting rouleaux formation"]','C','Oestrogen-containing oral contraceptives are a well-established secondary thrombophilic risk factor. They increase hepatic synthesis of procoagulant factors (II, VII, VIII, X, fibrinogen) and reduce protein S levels, shifting the coagulation balance towards a prothrombotic state. The risk is amplified in carriers of inherited thrombophilia such as factor V Leiden.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','hard','mcq','Protein C deficiency predisposes to thrombosis by which mechanism?','["A) Protein C deficiency reduces TFPI (tissue factor pathway inhibitor), allowing unrestricted extrinsic pathway activation", "B) Protein C is required for fibrinolysis via plasminogen activation; its deficiency prevents clot dissolution", "C) Protein C normally activates antithrombin III; its deficiency prevents neutralisation of thrombin", "D) Activated protein C (APC) normally inactivates factors Va and VIIIa; its deficiency allows these cofactors to persist, amplifying thrombin generation"]','D','Activated protein C (APC), formed when thrombin binds thrombomodulin on endothelial cells, is a key anticoagulant that proteolyses and inactivates factor Va and factor VIIIa. Protein C deficiency prevents this negative feedback, allowing factors Va and VIIIa to persist and drive excessive thrombin production, predisposing to venous thrombosis.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','medium','mcq','What morphological feature in a thrombus helps distinguish an antemortem pulmonary embolus from a post-mortem clot on gross examination?','["A) Lines of Zahn (alternating pale and red laminations) in the thrombus", "B) Central pale consolidation with surrounding haemorrhage", "C) Red-brown haemorrhagic wedge-shaped infarct at the lung periphery with pleural fibrinous exudate", "D) Bilateral symmetrical consolidation with normal pulmonary vessels"]','A','Lines of Zahn are alternating pale layers of platelets and fibrin with red layers of trapped erythrocytes, produced by the flowing blood during antemortem thrombus formation. These lines distinguish an antemortem thrombus (e.g., a pulmonary embolus) from a post-mortem clot, which forms from stagnant blood and lacks lines of Zahn.','universal',false,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','medium','mcq','A 25-year-old woman has recurrent second-trimester pregnancy losses and a single episode of DVT. Lupus anticoagulant is positive on two occasions 12 weeks apart. What is the most likely underlying condition?','["A) Hereditary protein S deficiency", "B) Antiphospholipid syndrome (APS)", "C) Factor V Leiden heterozygosity", "D) Prothrombin G20210A mutation"]','B','The combination of recurrent pregnancy loss (particularly second-trimester) and venous thrombosis, with persistently positive lupus anticoagulant on two occasions at least 12 weeks apart, meets clinical and laboratory criteria for antiphospholipid syndrome. APS may be primary or secondary to SLE. Treatment involves anticoagulation and aspirin during pregnancy.','universal',true,'{{"year1","year2","year3","year4","year5","year6","practitioner"}}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');